    { ...valid, unknown: true },
    { ...valid, version: 3 },
    { ...valid, version: 1, name: 'Café' },
    { ...valid, version: 2, name: undefined },
  ])
    assert.equal(decodeSnapshot(JSON.stringify(malformed)), null);
});
